import test from 'node:test';
import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import {correctProductData} from './product-title-corrections.mjs';
const rows=[{id:'4eal5Q0HLTcrspjkUwee',titulo:'Redmi Buds 6 Play Fone De Ouvido Bluetooth Sem Fio Cor Azul',listing:'MLB5096586835'},{id:'51ek2WOgqwYGnIqBAEPP',titulo:'Parafusadeira Furadeira De Impacto The Black Tools Com Maleta + Kit Acessórios 147 Peças 2 Baterias Profissional Tbkit17',listing:'MLB6644496628'}];
test('triagem52 preserva operação e rejeita outra identidade, com idempotência',()=>{for(const r of rows){const p={...r,preco:'99,99',linkAfiliado:'https://meli.la/preservado',variation_id:'original'},x=correctProductData(p);for(const k of Object.keys(p).filter(k=>k!=='titulo'))assert.equal(x[k],p[k]);assert.deepEqual(correctProductData(x),x);for(const alt of [{titulo:'Capa para '+r.titulo},{id:'outro'},{link:'https://www.mercadolivre.com.br/p/MLB12345678?wid=MLB9999999999'}])assert.equal(correctProductData({...p,comentario:'preservar',...alt}).comentario,'preservar');assert.ok(x.titulo.length<=100);}});
test('Redmi não converte estojo em autonomia contínua ou assistente próprio',()=>{const x=correctProductData(rows[0]);assert.equal(x.titulo,rows[0].titulo);assert.match(x.comentario,/até 7,5 horas por carga.*até 36 horas somando recargas/);assert.match(x.comentario,/não um assistente Xiaomi independente/);assert.match(x.comentario,/não ANC para ouvir/);assert.match(x.comentario,/não ao estojo/);});
test('TBKIT17 modifica só o título preservando resumo e campos fornecidos',()=>{const p={...rows[1],comentario:'Resumo original',pros:'Pros original',contras:'Contras original'},x=correctProductData(p);for(const k of Object.keys(p).filter(k=>k!=='titulo'))assert.equal(x[k],p[k]);assert.match(x.titulo,/TBKIT17/);assert.ok(x.titulo.length<=100);});
test('Atlas fica sem edição específica nesta triagem',()=>{const p={id:'5628K1uP7AHSdoBGcgZ1',titulo:'Cooktop 5 Bocas A Gás Atlas Agile Up Mega Chama Preto',comentario:'Texto preservado'},x=correctProductData(p);for(const k of Object.keys(p))assert.equal(x[k],p[k]);});
test('Redmi conserva categoria TWS e os sete campos documentados existentes de comparação',async()=>{const c=JSON.parse(await readFile(new URL('../informational-catalogue.json',import.meta.url),'utf8'));const p=c.products.find(x=>x.id===rows[0].id);assert.equal(p.comparison.family,'fone-tws');assert.equal(p.comparison.features.length,7);assert.deepEqual(correctProductData({...rows[0],comparison:p.comparison}).comparison,p.comparison);assert.ok(p.comparison.features.every(x=>x.checkedAt==='2026-10-19'));});
